riptTranslator\n---@field name_space string\n---@field lang_name string\n---@field memorize_callback fun(ce: CommitEntry)\n---@field max_homophones integer\n---@field spelling_hints integer\n---@field always_show_comments boolean\n---@field enable_correction boolean\n---@field delimiters string\n---@field tag string\n---@field enable_completion boolean\n---@field contextual_suggestions boolean\n---@field strict_spelling boolean\n---@field initial_quality number\n---@field preedit_formatter Projection\n---@field comment_formatter Projection\n---@field dict Dictionary\n---@field user_dict UserDictionary\n---@field translator Translator\n---@field query fun(self: self, input: string, segment: Segment): Translation|nil\n---@field start_session fun(self: self): boolean\n---@field finish_session fun(self: self): boolean\n---@field discard_session fun(self: self): boolean\n---@field memorize fun(self: self, callback: fun(ce: CommitEntry))\n---@field update_entry fun(self: self, entry: DictEntry, commits: integer, prefix: string): boolean\n---@field reload_user_dict_disabling_patterns fun(self: self, config_list: ConfigList): boolean\n---@field set_memorize_callback fun(self: self, callback: fun(ce: CommitEntry))\n---@field disconnect fun(self: self)\n\n---@class TableTranslator\n---@field name_space string\n---@field lang_name string\n---@field memorize_callback fun(ce: CommitEntry)\n---@field enable_charset_filter boolean\n---@field enable_encoder boolean\n---@field enable_sentence boolean\n---@field sentence_over_completion boolean\n---@field encode_commit_history boolean\n---@field max_phrase_length integer\n---@field max_homographs integer\n---@field delimiters string\n---@field tag string\n---@field enable_completion boolean\n---@field contextual_suggestions boolean\n---@field strict_spelling boolean\n---@field initial_quality number\n---@field preedit_formatter Projection\n---@field comment_formatter Projection\n---@field dict Dictionary\n---@field user_dict UserDictionary\n---@field translator Translator\n---@field query fun(self: self, input: string, segment: Segment): Translation|nil\n---@field start_session fun(self: self): boolean\n---@field finish_session fun(self: self): boolean\n---@field discard_session fun(self: self): boolean\n---@field memorize fun(self: self, callback: fun(ce: CommitEntry))\n---@field update_entry fun(self: self, entry: DictEntry, commits: integer, prefix: string): boolean\n---@field reload_user_dict_disabling_patterns fun(self: self, config_list: ConfigList): boolean\n---@field set_memorize_callback fun(self: self, callback: fun(ce: CommitEntry))\n---@field disconnect fun(self: self)\n\n---@class Filter\n---@field name_space string\n---@field apply fun(self: self, translation: Translation): Translation\n\n--- connect() 返回 Connection；组件持有连接时应在 fini/release 中 disconnect()。\n---@class Notifier\n---@field connect fun(self: self, f: fun(ctx: Context), group: integer|nil): Connection\n\n---@class OptionUpdateNotifier: Notifier\n---@field connect fun(self: self, f: fun(ctx: Context, name: string), group: integer|nil): Connection\n\n---@class PropertyUpdateNotifier: Notifier\n---@field connect fun(self: self, f: fun(ctx: Context, name: string), group: integer|nil): Connection\n\n---@class KeyEventNotifier: Notifier\n---@field connect fun(self: self, f: fun(ctx: Context, key: KeyEvent), group: integer|nil): Connection\n\n---@class Connection\n---@field disconnect fun(self: self)\n\n---@class Switcher\n---@field attached_engine Engine\n---@field user_config Config\n---@field active boolean\n---@field process_key fun(self: self, key_event: KeyEvent): boolean\n---@field select_next_schema fun(self: self)\n---@field is_auto_save fun(self: self, option: string): boolean\n---@field refresh_menu fun(self: self)\n---@field activate fun(self: self)\n---@field deactivate fun(self: self)\n\n---@param engine Engine\n---@return Switcher\nfunction Switcher(engine) end\n\n---@class CommitRecord\n---@field text string\n---@field type string\n\n---@class CommitHistory\n---@field size integer\n---@field push fun(self: self, key_event: KeyEvent)\n---@field back fun(self: self): CommitRecord|nil\n---@field to_table fun(self: self): CommitRecord[]\n---@field iter fun(self: self): fun(): (number, CommitRecord)|nil\n---@field latest_text fun(self: self): string\n---@field empty fun(self: self): boolean\n---@field clear fun(self: self)\n---@field pop_back fun(self: self)\n\n---@class DbAccessor\n---@field reset fun(self: self): boolean\n---@field jump fun(self: self, prefix: string): boolean\n--- 遍历 query() 结果，迭代返回 key, value。\n---@field iter fun(self: self): fun(): (string, string) | nil\n\n--- UserDb/LevelDb 使用前应确认 loaded()，未加载时调用 open()；不用时可 close()。\n---@class UserDb\n---@field _loaded boolean\n---@field read_only boolean\n---@field disabled boolean\n---@field name string\n---@field file_name string\n---@field open fun(self: self): boolean\n---@field open_read_only fun(self: self): boolean\n---@field close fun(self: self): boolean\n---@field query fun(self: self, prefix: string): DbAccessor\n---@field fetch fun(self: self, key: string): string|nil\n---@field update fun(self: self, key: string, value: string): boolean\n---@field erase fun(self: self, key: string): boolean\n---@field loaded fun(self: self): boolean\n---@field disable fun(self: self): boolean\n---@field enable fun(self: self): boolean\n\n---@param db_name string\n---@param db_class string\n---@return UserDb\nfunction UserDb(db_name, db_class) end\n\n---@class LevelDb: UserDb\n\n---@param db_name string\n---@return LevelDb\nfunction LevelDb(db_name) end\n\n---@class TableDb: UserDb\n\n---@param db_name string\n---@return TableDb\nfunction TableDb(db_name) end\n", "@numen-rime.librime")(...) end
package.preload["numen-core.parser"] = function(...) return load("--- Recursive-descent parser producing an AST:\n---   {kind=\"num\", v}\n---   {kind=\"clock\", h, m}\n---   {kind=\"datelit\", y, m, d}\n---   {kind=\"datetime\", tkind}           tkind: \"date\"|\"time\"|\"datetime\"\n---   {kind=\"qty\", v, unit}\n---   {kind=\"compound\", v, dim, factor, label}\n---   {kind=\"cur\", v, code}\n---   {kind=\"percent\", n}\n---   {kind=\"percentof\", n, inner}\n---   {kind=\"tipadd\", base, n}\n---   {kind=\"convert\", inner, target}    target: {kind=\"unit\"|\"cur\"|\"temporal\", ...}\n---   {kind=\"bin\", op, lhs, rhs}         op: \"add\"|\"sub\"|\"mul\"|\"div\"|\"pow\"\n---   {kind=\"funcall\", name, args}       args: 表达式列表（0 个或多个）\n\nlocal unit = require(\"numen-core.unit\")\n\nlocal M = {}\n\nlocal lookup_unit = unit.lookup_unit\nlocal lookup_currency = unit.lookup_currency\nlocal Dim = unit.Dim\n\n--- Tolerate unbalanced parentheses (the user is still typing):\n--- a stray `)` closes the whole preceding expression (`1 + 2)x2` -> `(1 + 2)x2`),\n--- missing `)` are appended at the end.\nlocal function balance_parens(tokens)\n  local depth = 0\n  local out = {}\n  for _, t in ipairs(tokens) do\n    if t.kind == \"lparen\" then\n      depth = depth + 1\n      out[#out + 1] = t\n    elseif t.kind == \"rparen\" and depth == 0 then\n      -- stray `)`: wrap everything so far in parens\n      if #out > 0 then\n        table.insert(out, 1, { kind = \"lparen\" })\n        out[#out + 1] = t\n      end\n    elseif t.kind == \"rparen\" then\n      depth = depth - 1\n      out[#out + 1] = t\n    else\n      out[#out + 1] = t\n    end\n  end\n  for _ = 1, depth do\n    out[#out + 1] = { kind = \"rparen\" }\n  end\n  return out\nend\n\nlocal function fmt_tok(t)\n  if t == nil then\n    return \"<eof>\"\n  end\n  return t.kind\nend\n\n--- 数学函数名（跟随 `(` 时按函数调用解析），实现见 eval.lua\nM.FUNCTION_NAMES = {\n  sin = true,\n  sinh = true,\n  asin = true,\n  cos = true,\n  cosh = true,\n  acos = true,\n  tan = true,\n  tanh = true,\n  atan = true,\n  atan2 = true,\n  deg = true,\n  rad = true,\n  exp = true,\n  sqrt = true,\n  log = true,\n  loge = true,\n  log10 = true,\n  avg = true,\n  var = true,\n  fact = true,\n  ldexp = true,\n  frexp = true,\n  random = true,\n  rdm = true,\n}\n\n--- 数学常量\nlocal CONSTANTS = {\n  pi = math.pi,\n  e = math.exp(1),\n}\n\nlocal Parser = {}\nParser.__index = Parser\n\nfunction Parser:peek()\n  return self.toks[self.pos]\nend\n\nfunction Parser:peek_at(offset)\n  return self.toks[self.pos + offset]\nend\n\nfunction Parser:next()\n  local t = self.toks[self.pos]\n  if t then\n    self.pos = self.pos + 1\n  end\n  return t\nend\n\nfunction Parser:eat_kw(kw)\n  local t = self:peek()\n  if t and t.kind == \"ident\" and t.s == kw then\n    self.pos = self.pos + 1\n    return true\n  end\n  return false\nend\n\nfunction Parser:parse_target()\n  local t = self:next()\n  if t == nil then\n    return nil, \"expected unit or currency, got <eof>\"\n  end\n  if t.kind == \"symbol\" then\n    local code = lookup_currency(t.c)\n    if code then\n      return { kind = \"cur\", code = code }\n    end\n    return nil, \"unknown currency symbol `\" .. t.c .. \"`\"\n  end\n  if t.kind == \"ident\" then\n    local name = t.s\n    -- 单位优先于货币：`to gb` 指 GB 而非英镑（英镑用 gbp）\n    local u = lookup_unit(name)\n    if u then\n      -- 复合目标单位：`to MB/s`、`to km/h`\n      local dim, factor, label = u.dim, u.factor, u.label\n      while true do\n        local slash = self:peek()\n        local nx = self:peek_at(1)\n        if not (slash and slash.kind == \"slash\" and nx and nx.kind == \"ident\" and lookup_unit(nx.s)) then\n          break\n        end\n        self.pos = self.pos + 2\n        local u2 = lookup_unit(nx.s)\n        dim = Dim.div(dim, u2.dim)\n        factor = factor / u2.factor\n        label = label .. \"/\" .. u2.label\n      end\n      return { kind = \"unit\", unit = { dim = dim, factor = factor, label = label } }\n    end\n    local code = lookup_currency(name)\n    if code then\n      return { kind = \"cur\", code = code }\n    end\n    if name == \"date\" or name == \"time\" or name == \"datetime\" then\n      return { kind = \"temporal\", tkind = name }\n    end\n    return nil, \"unknown conversion target `\" .. name .. \"`\"\n  end\n  return nil, \"expected unit or currency, got \" .. fmt_tok(t)\nend\n\n--- convert := postfix ((\"to\" | \"in\") target)*\n--- conversion binds tighter than `*`/`/`/`+`/`-`.\n--- Temporal targets are left for the top level.\nfunction Parser:parse_convert()\n  local e, err = self:parse_postfix()\n  if not e then\n    return nil, err\n  end\n  while true do\n    local t = self:peek()\n    local is_convert = t and t.kind == \"ident\" and (t.s == \"to\" or t.s == \"in\")\n    if not is_convert then\n      break\n    end\n    local nx = self:peek_at(1)\n    local temporal_target = nx and nx.kind == \"ident\" and (nx.s == \"date\" or nx.s == \"time\" or nx.s == \"datetime\")\n    if temporal_target then\n      break\n    end\n    self.pos = self.pos + 1\n    local target\n    target, err = self:parse_target()\n    if not target then\n      return nil, err\n    end\n    e = { kind = \"convert\", inner = e, target = target }\n  end\n  return e\nend\n\n--- add := mul ((\"+\" | \"-\") mul \"tip\"?)*\nfunction Parser:parse_add()\n  local e, err = self:parse_mul()\n  if not e then\n    return nil, err\n  end\n  while true do\n    local t = self:peek()\n    local op\n    if t and t.kind == \"plus\" then\n      op = \"add\"\n    elseif t and t.kind == \"minus\" then\n      op = \"sub\"\n    else\n      break\n    end\n    self.pos = self.pos + 1\n    local rhs\n    rhs, err = self:parse_mul()\n    if not rhs then\n      return nil, err\n    end\n    -- `x + n% tip` sugar\n    if rhs.kind == \"percent\" and op == \"add\" and self:eat_kw(\"tip\") then\n      e = { kind = \"tipadd\", base = e, n = rhs.n }\n    else\n      e = { kind = \"bin\", op = op, lhs = e, rhs = rhs }\n    end\n  end\n  return e\nend\n\n--- mul := pow ((\"of\" | \"*\" | \"x\" | \"/\") pow)*\nfunction Parser:parse_mul()\n  local e, err = self:parse_pow()\n  if not e then\n    return nil, err\n  end\n  while true do\n    local t = self:peek()\n    if t and t.kind == \"ident\" and t.s == \"of\" then\n      self.pos = self.pos + 1\n      if e.kind ~= \"percent\" then\n        return nil, \"`of` requires a percentage on the left\"\n      end\n      local rhs\n      rhs, err = self:parse_pow()\n      if not rhs then\n        return nil, err\n      end\n      e = { kind = \"percentof\", n = e.n, inner = rhs }\n    elseif t and t.kind == \"star\" then\n      self.pos = self.pos + 1\n      local rhs\n      rhs, err = self:parse_pow()\n      if not rhs then\n        return nil, err\n      end\n      e = { kind = \"bin\", op = \"mul\", lhs = e, rhs = rhs }\n    elseif t and t.kind == \"ident\" and t.s == \"x\" then\n      -- `x` as a multiplication sign: `5d x 120km/h`\n      self.pos = self.pos + 1\n      local rhs\n      rhs, err = self:parse_pow()\n      if not rhs then\n        return nil, err\n      end\n      e = { kind = \"bin\", op = \"mul\", lhs = e, rhs = rhs }\n    elseif t and t.kind == \"slash\" then\n      self.pos = self.pos + 1\n      local rhs\n      rhs, err = self:parse_pow()\n      if not rhs then\n        return nil, err\n      end\n      e = { kind = \"bin\", op = \"div\", lhs = e, rhs = rhs }\n    else\n      break\n    end\n  end\n  return e\nend\n\n--- pow := convert (\"^\" pow)?   右结合：`2^3^2` = `2^(3^2)` = 512\nfunction Parser:parse_pow()\n  local e, err = self:parse_convert()\n  if not e then\n    return nil, err\n  end\n  local t = self:peek()\n  if t and t.kind == \"caret\" then\n    self.pos = self.pos + 1\n    local rhs\n    rhs, err = self:parse_pow()\n    if not rhs then\n      return nil, err\n    end\n    e = { kind = \"bin\", op = \"pow\", lhs = e, rhs = rhs }\n  end\n  return e\nend\n\n--- postfix := primary (unit | currency | \"/\" unit | \"!\")*\nfunction Parser:parse_postfix()\n  local e, err = self:parse_primary()\n  if not e then\n    return nil, err\n  end\n  while true do\n    local t = self:peek()\n    if t and t.kind == \"ident\" then\n      local applied = false\n      if e.kind == \"num\" then\n        -- 单位优先于货币：`1 GB` 指吉字节而非英镑（英镑用 gbp）\n        local u = lookup_unit(t.s)\n        if u then\n          self.pos = self.pos + 1\n          e = { kind = \"qty\", v = e.v, unit = u }\n          applied = true\n        else\n          local code = lookup_currency(t.s)\n          if code then\n            self.pos = self.pos + 1\n            e = { kind = \"cur\", v = e.v, code = code }\n            applied = true\n          end\n        end\n      end\n      if not applied then\n        break\n      end\n    elseif t and t.kind == \"symbol\" then\n      if e.kind == \"num\" then\n        local code = lookup_currency(t.c)\n        if not code then\n          return nil, \"unknown currency symbol `\" .. t.c .. \"`\"\n        end\n        self.pos = self.pos + 1\n        e = { kind = \"cur\", v = e.v, code = code }\n      else\n        break\n      end\n    elseif t and t.kind == \"percent\" then\n      if e.kind == \"num\" then\n        self.pos = self.pos + 1\n        e = { kind = \"percent\", n = e.v }\n      else\n        break\n      end\n    elseif t and t.kind == \"bang\" then\n      -- 阶乘后缀：`5!`、`(1+2)!`\n      self.pos = self.pos + 1\n      e = { kind = \"funcall\", name = \"fact\", args = { e } }\n    elseif t and t.kind == \"slash\" then\n      -- compound unit: quantity / unit, e.g. `100 km/h`\n      local nx = self:peek_at(1)\n      local is_compound = nx and nx.kind == \"ident\" and lookup_unit(nx.s) ~= nil\n      local is_qty = e.kind == \"qty\" or e.kind == \"compound\"\n      if not (is_compound and is_qty) then\n        break\n      end\n      self.pos = self.pos + 1 -- '/'\n      local name = self:next().s\n      local u = lookup_unit(name)\n      if e.kind == \"qty\" then\n        e = {\n          kind = \"compound\",\n          v = e.v,\n          dim = Dim.div(e.unit.dim, u.dim),\n          factor = e.unit.factor / u.factor,\n          label = e.unit.label .. \"/\" .. u.label,\n        }\n      else\n        e = {\n          kind = \"compound\",\n          v = e.v,\n          dim = Dim.div(e.dim, u.dim),\n          factor = e.factor / u.factor,\n          label = e.label .. \"/\" .. u.label,\n        }\n      end\n    else\n      break\n    end\n  end\n  return e\nend\n\n--- primary := number | clock | symbol number | currency number | unit number\n---          | \"date\" | \"datetime\" | \"-\" primary | \"(\" add \")\"\nfunction Parser:parse_primary()\n  local t = self:peek()\n  if t == nil then\n    return nil, \"unexpected token <eof>\"\n  end\n  if t.kind == \"lparen\" then\n    self.pos = self.pos + 1\n    local e, err = self:parse_add()\n    if not e then\n      return nil, err\n    end\n    local c = self:peek()\n    if c and c.kind == \"rparen\" then\n      self.pos = self.pos + 1\n    else\n      return nil, \"expected `)`, got \" .. fmt_tok(c)\n    end\n    return e\n  end\n  if t.kind == \"num\" then\n    self.pos = self.pos + 1\n    return { kind = \"num\", v = t.v }\n  end\n  if t.kind == \"clock\" then\n    self.pos = self.pos + 1\n    return { kind = \"clock\", h = t.h, m = t.m }\n  end\n  if t.kind == \"datelit\" then\n    self.pos = self.pos + 1\n    return { kind = \"datelit\", y = t.y, m = t.m, d = t.d }\n  end\n  if t.kind == \"minus\" then\n    self.pos = self.pos + 1\n    -- 负号优先级低于 `^`：`-2^2` = `-(2^2)` = -4\n    local e, err = self:parse_pow()\n    if not e then\n      return nil, err\n    end\n    if e.kind == \"num\" then\n      return { kind = \"num\", v = -e.v }\n    end\n    return { kind = \"neg\", inner = e }\n  end\n  if t.kind == \"symbol\" then\n    self.pos = self.pos + 1\n    local code = lookup_currency(t.c)\n    if not code then\n      return nil, \"unknown currency symbol `\" .. t.c .. \"`\"\n    end\n    local nx = self:next()\n    if nx and nx.kind == \"num\" then\n      return { kind = \"cur\", v = nx.v, code = code }\n    end\n    return nil, \"expected number after `\" .. t.c .. \"`, got \" .. fmt_tok(nx)\n  end\n  if t.kind == \"ident\" then\n    local name = t.s\n    -- `log10(...)`、`atan2(...)`：词法上数字不入标识符，会切成名字+数字，在此拼回\n    local ntok = self:peek_at(1)\n    local lp = self:peek_at(2)\n    if ntok and ntok.kind == \"num\" and lp and lp.kind == \"lparen\" then\n      local joined = name .. tostring(ntok.v)\n      if M.FUNCTION_NAMES[joined] then\n        name = joined\n        self.pos = self.pos + 1\n      end\n    end\n    -- 函数调用：`sin(pi / 2)`、`avg(1, 2, 3)`、`random()`\n    local nx0 = self:peek_at(1)\n    if M.FUNCTION_NAMES[name] and nx0 and nx0.kind == \"lparen\" then\n      self.pos = self.pos + 2\n      local args = {}\n      local c = self:peek()\n      if not (c and c.kind == \"rparen\") then\n        while true do\n          local arg, aerr = self:parse_add()\n          if not arg then\n            return nil, aerr\n          end\n          args[#args + 1] = arg\n          local sep = self:peek()\n          if sep and sep.kind == \"comma\" then\n            self.pos = self.pos + 1\n          else\n            break\n          end\n        end\n      end\n      local close = self:peek()\n      if close and close.kind == \"rparen\" then\n        self.pos = self.pos + 1\n      else\n        return nil, \"expected `)`, got \" .. fmt_tok(close)\n      end\n      return { kind = \"funcall\", name = name, args = args }\n    end\n    -- 数学常量\n    local const = CONSTANTS[name]\n    if const then\n      self.pos = self.pos + 1\n      return { kind = \"const\", name = name, v = const }\n    end\n    if name == \"date\" or name == \"today\" then\n      self.pos = self.pos + 1\n      return { kind = \"datetime\", tkind = \"date\" }\n    end\n    if name == \"time\" then\n      self.pos = self.pos + 1\n      return { kind = \"datetime\", tkind = \"time\" }\n    end\n    if name == \"datetime\" or name == \"now\" then\n      self.pos = self.pos + 1\n      return { kind = \"datetime\", tkind = \"datetime\" }\n    end\n    -- prefix unit/currency: `rmb 10`, `km 5`\n    local u0 = lookup_unit(name)\n    if u0 then\n      self.pos = self.pos + 1\n      local nx = self:next()\n      if nx and nx.kind == \"num\" then\n        return { kind = \"qty\", v = nx.v, unit = u0 }\n      end\n      return nil, \"expected number after `\" .. name .. \"`, got \" .. fmt_tok(nx)\n    end\n    local code = lookup_currency(name)\n    if code then\n      self.pos = self.pos + 1\n      local nx = self:next()\n      if nx and nx.kind == \"num\" then\n        return { kind = \"cur\", v = nx.v, code = code }\n      end\n      return nil, \"expected number after `\" .. name .. \"`, got \" .. fmt_tok(nx)\n    end\n    return nil, \"unknown word `\" .. name .. \"`\"\n  end\n  return nil, \"unexpected token \" .. fmt_tok(t)\nend\n\nM.balance_parens = balance_parens\n\nfunction M.parse(tokens)\n  if #tokens == 0 then\n    return nil, \"empty input\"\n  end\n  tokens = balance_parens(tokens)\n  local p = setmetatable({ toks = tokens, pos = 1 }, Parser)\n  local e, err = p:parse_add()\n  if not e then\n    return nil, err\n  end\n  -- 顶层换算作用于整个表达式（如 `12:03 + 1d to datetime`）。\n  while p:eat_kw(\"to\") or p:eat_kw(\"in\") do\n    local target\n    target, err = p:parse_target()\n    if not target then\n      return nil, err\n    end\n    e = { kind = \"convert\", inner = e, target = target }\n  end\n  if p.pos <= #tokens then\n    return nil, \"unexpected trailing token \" .. fmt_tok(tokens[p.pos])\n  end\n  return e\nend\n\nreturn M\n", "@numen-core.parser")(...) end
package.preload["numen-core.unit"] = function(...) return load("--- Physical units, currency aliases and exchange-rate handling.\n--- Rates are loaded from a JSON file (fawazahmed0/currency-api format,\n--- base EUR): `{\"date\": \"...\", \"eur\": {\"cny\": 7.5, ...}}`.\n\nlocal json = require(\"numen-core.jsonlite\")\n\nlocal M = {}\n\n-- Dimension helpers: a dim is a map of exponents, e.g. {l=1} length,\n-- {m=1} mass, {t=1} time, {d=1} data, {p=1} power, {l=1,t=-1} speed.\nlocal Dim = {}\nM.Dim = Dim\n\nlocal DIM_KEYS = { \"l\", \"m\", \"t\", \"d\", \"p\" }\n\nDim.NONE = { l = 0, m = 0, t = 0 }\nDim.LENGTH = { l = 1 }\nDim.MASS = { m = 1 }\nDim.TIME = { t = 1 }\nDim.DATA = { d = 1 }\nDim.POWER = { p = 1 }\nDim.SPEED = { l = 1, t = -1 }\nDim.DATA_RATE = { d = 1, t = -1 }\n\nfunction Dim.mul(a, b)\n  local r = {}\n  for _, k in ipairs(DIM_KEYS) do\n    r[k] = (a[k] or 0) + (b[k] or 0)\n  end\n  return r\nend\n\nfunction Dim.div(a, b)\n  local r = {}\n  for _, k in ipairs(DIM_KEYS) do\n    r[k] = (a[k] or 0) - (b[k] or 0)\n  end\n  return r\nend\n\nfunction Dim.eq(a, b)\n  for _, k in ipairs(DIM_KEYS) do\n    if (a[k] or 0) ~= (b[k] or 0) then\n      return false\n    end\n  end\n  return true\nend\n\nfunction Dim.is_none(a)\n  return Dim.eq(a, Dim.NONE)\nend\n\n---@class UnitDef\n---@field dim table\n---@field factor number value of 1 unit in base units of its dim\n---@field label string\n---@field aliases string[]\n\n-- 十进制/二进制字节单位的可切换进位（见 M.set_binary_bytes）\nlocal BYTE_SCALE = 1000\nlocal BYTE_UNITS = {} -- 需要随进位调整的十进制字节单位\n\n---@type UnitDef[]\nM.UNITS = {\n  -- length (base: m)\n  { dim = Dim.LENGTH, factor = 1, label = \"m\", aliases = { \"m\", \"meter\", \"meters\", \"米\" } },\n  { dim = Dim.LENGTH, factor = 1000, label = \"km\", aliases = { \"km\", \"kilometer\", \"kilometers\", \"千米\", \"公里\" } },\n  { dim = Dim.LENGTH, factor = 0.01, label = \"cm\", aliases = { \"cm\", \"centimeter\", \"centimeters\", \"厘米\" } },\n  { dim = Dim.LENGTH, factor = 0.001, label = \"mm\", aliases = { \"mm\", \"millimeter\", \"millimeters\", \"毫米\" } },\n  { dim = Dim.LENGTH, factor = 1609.344, label = \"mi\", aliases = { \"mi\", \"mile\", \"miles\", \"英里\" } },\n  { dim = Dim.LENGTH, factor = 0.9144, label = \"yd\", aliases = { \"yd\", \"yard\", \"yards\", \"码\" } },\n  { dim = Dim.LENGTH, factor = 0.3048, label = \"ft\", aliases = { \"ft\", \"foot\", \"feet\", \"英尺\" } },\n  { dim = Dim.LENGTH, factor = 0.0254, label = \"in\", aliases = { \"inch\", \"inches\", \"英寸\" } },\n  -- mass (base: g)\n  { dim = Dim.MASS, factor = 1, label = \"g\", aliases = { \"g\", \"gram\", \"grams\", \"克\" } },\n  { dim = Dim.MASS, factor = 1000, label = \"kg\", aliases = { \"kg\", \"kilogram\", \"kilograms\", \"千克\", \"公斤\" } },\n  { dim = Dim.MASS, factor = 1e6, label = \"t\", aliases = { \"t\", \"ton\", \"tons\", \"tonne\", \"tonnes\", \"吨\" } },\n  { dim = Dim.MASS, factor = 453.59237, label = \"lb\", aliases = { \"lb\", \"lbs\", \"pound\", \"pounds\", \"磅\" } },\n  -- 中文质量单位仅用于美化输出（display_only，不参与输入解析）\n  { dim = Dim.MASS, factor = 500, label = \"斤\", display_only = true },\n  { dim = Dim.MASS, factor = 50, label = \"两\", display_only = true },\n  { dim = Dim.MASS, factor = 5, label = \"钱\", display_only = true },\n  { dim = Dim.MASS, factor = 50000, label = \"担\", display_only = true },\n  -- time (base: s)\n  { dim = Dim.TIME, factor = 1, label = \"s\", aliases = { \"s\", \"sec\", \"secs\", \"second\", \"seconds\", \"秒\" } },\n  { dim = Dim.TIME, factor = 60, label = \"min\", aliases = { \"min\", \"mins\", \"minute\", \"minutes\", \"分钟\" } },\n  { dim = Dim.TIME, factor = 3600, label = \"h\", aliases = { \"h\", \"hr\", \"hrs\", \"hour\", \"hours\", \"小时\" } },\n  { dim = Dim.TIME, factor = 86400, label = \"day\", aliases = { \"d\", \"day\", \"days\", \"天\", \"日\" } },\n  -- data (base: byte)；KB/MB/GB/TB 的进位可用 M.set_binary_bytes 切换\n  { dim = Dim.DATA, factor = 0.125, label = \"bit\", aliases = { \"bit\", \"bits\" } },\n  { dim = Dim.DATA, factor = 1, label = \"B\", aliases = { \"b\", \"byte\", \"bytes\" } },\n  { dim = Dim.DATA, factor = BYTE_SCALE, label = \"KB\", aliases = { \"kb\" } },\n  { dim = Dim.DATA, factor = BYTE_SCALE ^ 2, label = \"MB\", aliases = { \"mb\" } },\n  { dim = Dim.DATA, factor = BYTE_SCALE ^ 3, label = \"GB\", aliases = { \"gb\" } },\n  { dim = Dim.DATA, factor = BYTE_SCALE ^ 4, label = \"TB\", aliases = { \"tb\" } },\n  { dim = Dim.DATA, factor = 1024, label = \"KiB\", aliases = { \"kib\" } },\n  { dim = Dim.DATA, factor = 1024 ^ 2, label = \"MiB\", aliases = { \"mib\" } },\n  { dim = Dim.DATA, factor = 1024 ^ 3, label = \"GiB\", aliases = { \"gib\" } },\n  { dim = Dim.DATA, factor = 1024 ^ 4, label = \"TiB\", aliases = { \"tib\" } },\n  -- speed (base: m/s)；km/h 之类的复合写法也可直接输入\n  { dim = Dim.SPEED, factor = 1, label = \"m/s\", aliases = { \"mps\" } },\n  { dim = Dim.SPEED, factor = 1000 / 3600, label = \"km/h\", aliases = { \"kmh\", \"kph\" } },\n  { dim = Dim.SPEED, factor = 0.44704, label = \"mph\", aliases = { \"mph\" } },\n  -- data rate (base: byte/s)；`MB/s` 走复合解析，mbps 等是独立别名\n  { dim = Dim.DATA_RATE, factor = 125, label = \"kbps\", aliases = { \"kbps\" } },\n  { dim = Dim.DATA_RATE, factor = 125000, label = \"mbps\", aliases = { \"mbps\" } },\n  { dim = Dim.DATA_RATE, factor = 125000000, label = \"gbps\", aliases = { \"gbps\" } },\n  -- power (base: W)\n  { dim = Dim.POWER, factor = 1, label = \"W\", aliases = { \"w\", \"watt\", \"watts\" } },\n  { dim = Dim.POWER, factor = 1000, label = \"kW\", aliases = { \"kw\" } },\n}\n\nfor _, u in ipairs(M.UNITS) do\n  if u.dim == Dim.DATA and (u.label == \"KB\" or u.label == \"MB\" or u.label == \"GB\" or u.label == \"TB\") then\n    BYTE_UNITS[#BYTE_UNITS + 1] = u\n  end\nend\n\n--- 切换十进制字节单位（KB/MB/GB/TB）的进位：false=1000（默认），true=1024。\nfunction M.set_binary_bytes(enabled)\n  BYTE_SCALE = enabled and 1024 or 1000\n  for i, u in ipairs(BYTE_UNITS) do\n    u.factor = BYTE_SCALE ^ i\n  end\nend\n\n-- 相近单位的展示梯度：按 label 引用上面的单位定义，窗口滑动展示。\n-- 输入解析只看英文缩写；这里允许混入中文等 display_only 单位。\nM.LADDERS = {\n  { dim = Dim.LENGTH, labels = { \"km\", \"m\", \"cm\", \"mm\" } },\n  { dim = Dim.MASS, labels = { \"t\", \"kg\", \"g\", \"斤\", \"两\", \"钱\" } },\n  { dim = Dim.TIME, labels = { \"day\", \"h\", \"min\", \"s\" } },\n  { dim = Dim.DATA, labels = { \"TB\", \"GB\", \"MB\", \"KB\", \"B\" } },\n  { dim = Dim.SPEED, labels = { \"km/h\", \"m/s\", \"mph\" } },\n  { dim = Dim.DATA_RATE, labels = { \"gbps\", \"mbps\", \"kbps\" } },\n  { dim = Dim.POWER, labels = { \"kW\", \"W\" } },\n}\n\n--- 找到某 dim 的展示梯度（ladder 为按 label 解析出的单位数组），没有则 nil。\nfunction M.ladder_for(dim)\n  for _, l in ipairs(M.LADDERS) do\n    if Dim.eq(l.dim, dim) then\n      local out = {}\n      for _, label in ipairs(l.labels) do\n        for _, u in ipairs(M.UNITS) do\n          if u.label == label then\n            out[#out + 1] = u\n            break\n          end\n        end\n      end\n      return out\n    end\n  end\n  return nil\nend\n\n-- alias (lowercase) -> currency code (uppercase)\nM.CURRENCIES = {\n  rmb = \"CNY\",\n  cny = \"CNY\",\n  yuan = \"CNY\",\n  [\"¥\"] = \"CNY\",\n  cn = \"CNY\",\n  [\"$\"] = \"USD\",\n  usd = \"USD\",\n  dollar = \"USD\",\n  dollars = \"USD\",\n  us = \"USD\",\n  [\"€\"] = \"EUR\",\n  eur = \"EUR\",\n  eu = \"EUR\",\n  [\"£\"] = \"GBP\",\n  gbp = \"GBP\",\n  gb = \"GBP\",\n  uk = \"GBP\",\n  jpy = \"JPY\",\n  yen = \"JPY\",\n  jp = \"JPY\",\n  hkd = \"HKD\",\n  hk = \"HKD\",\n  krw = \"KRW\",\n  kr = \"KRW\",\n  aud = \"AUD\",\n  au = \"AUD\",\n  cad = \"CAD\",\n  ca = \"CAD\",\n  chf = \"CHF\",\n  ch = \"CHF\",\n  sgd = \"SGD\",\n  sg = \"SGD\",\n}\n\nlocal UNIT_INDEX = {}\nfor _, unit in ipairs(M.UNITS) do\n  for _, alias in ipairs(unit.aliases or {}) do\n    UNIT_INDEX[alias] = unit\n  end\nend\n\n--- Look up a physical unit by alias. Input must already be lowercase.\nfunction M.lookup_unit(name)\n  return UNIT_INDEX[name]\nend\n\n--- 把汇率表中的货币代码注册为可用货币（如 thb -> THB）。\n--- 固定的 CURRENCIES 表只提供别名/符号映射，具体支持哪些币种由 rates 决定。\n--- Engine 加载汇率后调用。\nfunction M.register_currency_codes(rates)\n  for code in pairs(rates) do\n    if type(code) == \"string\" and #code >= 2 then\n      local lower = string.lower(code)\n      if not M.CURRENCIES[lower] then\n        M.CURRENCIES[lower] = string.upper(code)\n      end\n    end\n  end\nend\n\n--- Look up a currency code by alias. Input must already be lowercase.\nfunction M.lookup_currency(name)\n  return M.CURRENCIES[name]\nend\n\n--- All known currency codes (uppercase), deduplicated.\nfunction M.currency_codes()\n  local seen, out = {}, {}\n  for _, code in pairs(M.CURRENCIES) do\n    if not seen[code] then\n      seen[code] = true\n      out[#out + 1] = code\n    end\n  end\n  return out\nend\n\n--- Load an exchange-rate table from a JSON file path.\n--- Returns (rates, nil) or (nil, err). Keys are uppercase codes;\n--- values are units of `code` per 1 unit of the base currency (EUR).\nfunction M.load_rates(path)\n  local data, err = json.decode_file(path)\n  if not data then\n    return nil, \"cannot read rates file `\" .. tostring(path) .. \"`: \" .. tostring(err)\n  end\n  if type(data) ~= \"table\" or type(data.eur) ~= \"table\" then\n    return nil, \"rates file must contain the EUR base currency table\"\n  end\n  local rates = {}\n  for code, v in pairs(data.eur) do\n    if type(v) == \"number\" then\n      rates[string.upper(code)] = v\n    end\n  end\n  return rates\nend\n\n--- Convert `v` units of `from` into `to` using `rates`:\n--- `v / rate(from) * rate(to)`. Returns nil when a rate is missing.\nfunction M.convert_currency(rates, v, from, to)\n  local from_rate = rates[from]\n  local to_rate = rates[to]\n  if not from_rate or not to_rate or from_rate == 0 then\n    return nil\n  end\n  return v / from_rate * to_rate\nend\n\n--- Pick a nice display unit for a base-dim value: prefer the unit giving\n--- the smallest magnitude >= 1, falling back to the base unit.\nfunction M.best_unit(dim, base_value)\n  local best, best_v\n  for _, unit in ipairs(M.UNITS) do\n    if Dim.eq(unit.dim, dim) then\n      local v = base_value / unit.factor\n      if math.abs(v) >= 1 and (best == nil or math.abs(v) < math.abs(best_v)) then\n        best, best_v = unit, v\n      end\n    end\n  end\n  if best then\n    return best, best_v\n  end\n  for _, unit in ipairs(M.UNITS) do\n    if Dim.eq(unit.dim, dim) then\n      return unit, base_value / unit.factor\n    end\n  end\n  return nil\nend\n\nreturn M\n", "@numen-core.unit")(...) end
package.preload["numen-core.cnnum"] = function(...) return load("--- 中文数字与人民币金额格式化（仅简体）。\n--- 参考万象 super_calculator 的数字转换，裁剪为常用需求。\n\nlocal M = {}\n\nlocal LOWER_DIGITS = { \"零\", \"一\", \"二\", \"三\", \"四\", \"五\", \"六\", \"七\", \"八\", \"九\" }\nlocal UPPER_DIGITS = { \"零\", \"壹\", \"贰\", \"叁\", \"肆\", \"伍\", \"陆\", \"柒\", \"捌\", \"玖\" }\nlocal LOWER_PLACES = { \"\", \"十\", \"百\", \"千\" }\nlocal UPPER_PLACES = { \"\", \"拾\", \"佰\", \"仟\" }\nlocal GROUP_UNITS = { \"\", \"万\", \"亿\", \"万亿\" }\n\n-- 4 位一组转换（group 为 1~4 位数字字符串，高位在前）\nlocal function group_to_chinese(group, digits, places)\n  local result = \"\"\n  local pending_zero = false\n  for i = 1, #group do\n    local d = tonumber(group:sub(i, i))\n    local place = #group - i + 1\n    if d == 0 then\n      if result ~= \"\" then\n        pending_zero = true\n      end\n    else\n      if pending_zero then\n        result = result .. digits[1]\n        pending_zero = false\n      end\n      result = result .. digits[d + 1] .. places[place]\n    end\n  end\n  return result\nend\n\n--- 非负整数（数字字符串，<=16 位）转中文读数。\nlocal function integer_to_chinese(int_str, upper)\n  local digits = upper and UPPER_DIGITS or LOWER_DIGITS\n  local places = upper and UPPER_PLACES or LOWER_PLACES\n  int_str = int_str:gsub(\"^0+\", \"\")\n  if int_str == \"\" then\n    return digits[1]\n  end\n  if #int_str > 16 then\n    return nil\n  end\n  local groups = {}\n  for finish = #int_str, 1, -4 do\n    local start = math.max(1, finish - 3)\n    groups[#groups + 1] = int_str:sub(start, finish)\n  end\n  local result = \"\"\n  for i = #groups, 1, -1 do\n    local gv = tonumber(groups[i])\n    if gv == 0 then\n      -- 整组为 0：若前后都有内容，补一个零（由下一非零组处理）\n      if result ~= \"\" and i > 1 then\n        -- 检查更低组是否有非零\n        for j = i - 1, 1, -1 do\n          if tonumber(groups[j]) ~= 0 then\n            result = result .. digits[1]\n            break\n          end\n        end\n      end\n    else\n      if result ~= \"\" and gv < 1000 then\n        -- 与上一组之间夹零，如 10001 -> 一万零一\n        result = result .. digits[1]\n      end\n      result = result .. group_to_chinese(groups[i], digits, places) .. GROUP_UNITS[i]\n    end\n  end\n  if not upper then\n    result = result:gsub(\"^一十\", \"十\")\n  end\n  return result\nend\n\n--- 金额（元）转中文：返回 小写/大写 金额字符串。\n--- 超过分的小数按四舍五入到分。负数加“负”前缀。\n--- upper: true 用壹贰叁，false 用一二三。\nfunction M.money(v, upper)\n  local neg = v < 0\n  local cents = math.floor(math.abs(v) * 100 + 0.5)\n  local yuan = math.floor(cents / 100)\n  local jiao = math.floor((cents % 100) / 10)\n  local fen = cents % 10\n  local digits = upper and UPPER_DIGITS or LOWER_DIGITS\n\n  local yuan_str = integer_to_chinese(tostring(yuan), upper)\n  if not yuan_str then\n    return nil\n  end\n  local result = yuan_str .. \"元\"\n  if jiao == 0 and fen == 0 then\n    result = result .. \"整\"\n  else\n    if jiao > 0 then\n      result = result .. digits[jiao + 1] .. \"角\"\n    elseif yuan > 0 and fen > 0 then\n      result = result .. digits[1] -- 零几分\n    end\n    if fen > 0 then\n      result = result .. digits[fen + 1] .. \"分\"\n    end\n  end\n  if neg then\n    result = \"负\" .. result\n  end\n  return result\nend\n\n--- 整数读数（不含单位“元”），供纯数字使用。\nfunction M.integer(v, upper)\n  if v ~= math.floor(v) or math.abs(v) >= 1e16 then\n    return nil\n  end\n  local neg = v < 0\n  local s = integer_to_chinese(tostring(math.abs(v)), upper)\n  if not s then\n    return nil\n  end\n  return neg and (\"负\" .. s) or s\nend\n\nreturn M\n", "@numen-core.cnnum")(...) end
package.preload["numen-core.present"] = function(...) return load("--- Candidate formatter: values/candidates -> display strings.\n---\n--- Time format pattern tokens:\n---   Y 4-digit year, y 2-digit year, m/n month (padded/raw), d/j day (padded/raw),\n---   H hour (24h padded), I hour (12h raw), M minute, S second,\n---   P/p AM/PM (upper/lower), T literal T, O local timezone offset;\n--- other characters pass through unchanged.\n--- Formats containing `S` are skipped when seconds are 00.\n\nlocal cnnum = require(\"numen-core.cnnum\")\nlocal unit = require(\"numen-core.unit\")\n\nlocal M = {}\n\nlocal SYMBOLS = { CNY = \"¥\", USD = \"$\", EUR = \"€\", GBP = \"£\" }\n\nlocal function currency_symbol(code)\n  return SYMBOLS[code] or code\nend\n\n--- Round to `dp` decimals and render without trailing zeros.\nlocal function fmt_rounded(v, dp)\n  local mult = 10 ^ dp\n  local r = math.floor(math.abs(v) * mult + 0.5) / mult\n  if v < 0 then\n    r = -r\n  end\n  local s = string.format(\"%.\" .. dp .. \"f\", r)\n  s = s:gsub(\"0+$\", \"\"):gsub(\"%.$\", \"\")\n  if s == \"-0\" or s == \"\" then\n    s = \"0\"\n  end\n  return s\nend\n\nlocal function fmt_decimal(v)\n  -- integers render exactly; otherwise round to 6 decimal places\n  if v == math.floor(v) and math.abs(v) < 1e15 then\n    return string.format(\"%d\", v)\n  end\n  return fmt_rounded(v, 6)\nend\n\nlocal function fmt_money(v)\n  return fmt_rounded(v, 2)\nend\n\nlocal function pad2(n)\n  return string.format(\"%02d\", n)\nend\n\nlocal function render_temporal(dt, pattern)\n  local out = {}\n  local hour12 = dt.hour % 12\n  if hour12 == 0 then\n    hour12 = 12\n  end\n  local i = 1\n  local len = #pattern\n  while i <= len do\n    -- pattern bytes may be UTF-8; tokens are ASCII so scan byte-wise\n    local c = pattern:sub(i, i)\n    if c == \"Y\" then\n      out[#out + 1] = string.format(\"%04d\", dt.year)\n      i = i + 1\n    elseif c == \"y\" then\n      out[#out + 1] = pad2(dt.year % 100)\n      i = i + 1\n    elseif c == \"m\" then\n      out[#out + 1] = pad2(dt.month)\n      i = i + 1\n    elseif c == \"n\" then\n      out[#out + 1] = tostring(dt.month)\n      i = i + 1\n    elseif c == \"d\" then\n      out[#out + 1] = pad2(dt.day)\n      i = i + 1\n    elseif c == \"j\" then\n      out[#out + 1] = tostring(dt.day)\n      i = i + 1\n    elseif c == \"H\" then\n      out[#out + 1] = pad2(dt.hour)\n      i = i + 1\n    elseif c == \"I\" then\n      out[#out + 1] = tostring(hour12)\n      i = i + 1\n    elseif c == \"M\" then\n      out[#out + 1] = pad2(dt.min)\n      i = i + 1\n    elseif c == \"S\" then\n      out[#out + 1] = pad2(dt.sec)\n      i = i + 1\n    elseif c == \"P\" then\n      out[#out + 1] = dt.hour < 12 and \"AM\" or \"PM\"\n      i = i + 1\n    elseif c == \"p\" then\n      out[#out + 1] = dt.hour < 12 and \"am\" or \"pm\"\n      i = i + 1\n    elseif c == \"T\" then\n      out[#out + 1] = \"T\"\n      i = i + 1\n    elseif c == \"O\" then\n      -- local timezone offset, e.g. +08:00\n      local ok, z = pcall(os.date, \"%z\")\n      if ok and type(z) == \"string\" and #z == 5 then\n        out[#out + 1] = z:sub(1, 3) .. \":\" .. z:sub(4, 5)\n      end\n      i = i + 1\n    else\n      -- copy one UTF-8 char\n      local b = pattern:byte(i)\n      local size = 1\n      if b >= 0xF0 then\n        size = 4\n      elseif b >= 0xE0 then\n        size = 3\n      elseif b >= 0xC0 then\n        size = 2\n      end\n      out[#out + 1] = pattern:sub(i, i + size - 1)\n      i = i + size\n    end\n  end\n  return table.concat(out)\nend\n\n--- Presenter: build once with a FormatConfig, reuse for every input.\n---\n--- config fields (all optional):\n---   date_formats: string[]     (default {\"Y-m-d\"})\n---   time_formats: string[]     (default {\"H:M\", \"H:M:S\"})\n---   datetime_formats: string[] (default {\"Y-m-d H:M\", \"Y-m-d H:M:S\"})\n---   rmb_cn: boolean            (default true) 人民币结果附加中文金额候选\n---   nearby_units: boolean      (default true) 数量结果附加相近单位候选\nlocal Presenter = {}\nPresenter.__index = Presenter\nM.Presenter = Presenter\n\nfunction Presenter.new(config)\n  config = config or {}\n  local cfg = {\n    date_formats = config.date_formats or { \"Y-m-d\" },\n    time_formats = config.time_formats or { \"H:M\", \"H:M:S\" },\n    datetime_formats = config.datetime_formats or { \"Y-m-d H:M\", \"Y-m-d H:M:S\" },\n    rmb_cn = config.rmb_cn ~= false,\n    nearby_units = config.nearby_units ~= false,\n  }\n  return setmetatable({ config = cfg }, Presenter)\nend\n\n-- 相近单位的取值范围过滤：太小/太大的换算没有意义\nlocal NEARBY_MIN, NEARBY_MAX = 1e-3, 1e6\n\n--- 梯度上当前单位的位置：优先按 label 命中，否则按 factor 找第一个不大于它的位置。\nlocal function ladder_index(ladder, factor, label)\n  for i, u in ipairs(ladder) do\n    if u.label == label then\n      return i\n    end\n  end\n  for i, u in ipairs(ladder) do\n    if u.factor <= factor then\n      return i\n    end\n  end\n  return #ladder\nend\n\n--- 沿梯度滑动窗口（±2），产出当前单位之外、数值合理的相近单位展示串。\nlocal function nearby_variants(value)\n  local ladder = unit.ladder_for(value.dim)\n  if not ladder then\n    return {}\n  end\n  local idx = ladder_index(ladder, value.factor, value.label)\n  local out = {}\n  for i = math.max(1, idx - 2), math.min(#ladder, idx + 2) do\n    local u = ladder[i]\n    if u.label ~= value.label then\n      local v = value.v * value.factor / u.factor\n      if math.abs(v) >= NEARBY_MIN and math.abs(v) <= NEARBY_MAX then\n        out[#out + 1] = fmt_decimal(v) .. \" \" .. u.label\n      end\n    end\n  end\n  return out\nend\n\n--- Format a single value into all configured display variants\n--- (deduplicated, order preserved).\n--- opts.nearby: 是否附加相近单位（显式换算结果不需要）\nfunction Presenter:format_value(value, opts)\n  opts = opts or {}\n  if value.type == \"num\" then\n    return { fmt_decimal(value.v) }\n  end\n  if value.type == \"str\" then\n    return { value.s }\n  end\n  if value.type == \"qty\" then\n    local out = { fmt_decimal(value.v) .. \" \" .. value.label }\n    if self.config.nearby_units and opts.nearby then\n      for _, s in ipairs(nearby_variants(value)) do\n        out[#out + 1] = s\n      end\n    end\n    return out\n  end\n  if value.type == \"cur\" then\n    local out = { currency_symbol(value.code) .. fmt_money(value.v) }\n    if self.config.rmb_cn and value.code == \"CNY\" then\n      local lower = cnnum.money(value.v, false)\n      local upper = cnnum.money(value.v, true)\n      if lower then\n        out[#out + 1] = lower\n      end\n      if upper and upper ~= lower then\n        out[#out + 1] = upper\n      end\n    end\n    return out\n  end\n  -- temporal\n  local patterns\n  if value.kind == \"date\" then\n    patterns = self.config.date_formats\n  elseif value.kind == \"time\" then\n    patterns = self.config.time_formats\n  else\n    patterns = self.config.datetime_formats\n  end\n  local out = {}\n  for _, p in ipairs(patterns) do\n    -- 秒为 00 时，含 `S` 的格式会被跳过\n    if not (value.dt.sec == 0 and p:find(\"S\", 1, true)) then\n      local s = render_temporal(value.dt, p)\n      local dup = false\n      for _, existing in ipairs(out) do\n        if existing == s then\n          dup = true\n          break\n        end\n      end\n      if not dup then\n        out[#out + 1] = s\n      end\n    end\n  end\n  return out\nend\n\n--- 换算目标的展示名：`to kg` / `to rmb`\nlocal function target_desc(target)\n  if target.kind == \"unit\" then\n    return target.unit.label\n  end\n  if target.kind == \"cur\" then\n    return string.lower(target.code)\n  end\n  return target.tkind or \"\"\nend\n\n--- Format all candidates for display (deduplicated, order preserved).\nfunction Presenter:format_candidates(candidates)\n  local out = {}\n  local function push(s)\n    for _, existing in ipairs(out) do\n      if existing == s then\n        return\n      end\n    end\n    out[#out + 1] = s\n  end\n  for _, c in ipairs(candidates) do\n    local strings = self:format_value(c.value, { nearby = not c.exact })\n    for i, s in ipairs(strings) do\n      if c.not